"version 1\n"
"\n"
"display-variable \"show-issues\" type=\"bool\" default=true label=\"Issues\" icon=\"I\" persist=true\n"
"\n"
"display-variable \"show-finished\" type=\"bool\" default=false label=\"Show finished\" icon=\"F\" persist=true\n"
"\n"
"display-variable \"show-role-attempts\" type=\"bool\" default=false label=\"Role attempts\" icon=\"R\" persist=true\n"
"\n"
"// First matching rule wins: finished role attempts follow Show finished.\n"
"// Shared by tree and Attention; hidden open workspaces remain in the fallback.\n"
"visibility \"wheelhouse/activity\" {\n"
"  when kind=\"convoy\" visible-when=\"show-finished\" { match \"flotilla.convoy.superseded\" value=\"true\"; }\n"
"  when kind=\"vessel\" visible-when=\"show-finished\" { match \"flotilla.convoy.superseded\" value=\"true\"; }\n"
"  when kind=\"convoy\" visible-when=\"show-finished\" { match \"flotilla.convoy.phase\" value=\"landed\"; }\n"
"  when kind=\"vessel\" visible-when=\"show-finished\" { match \"flotilla.convoy.phase\" value=\"landed\"; }\n"
"  when kind=\"convoy\" visible-when=\"show-finished\" { match \"flotilla.convoy.phase\" value=\"cancelled\"; }\n"
"  when kind=\"vessel\" visible-when=\"show-finished\" { match \"flotilla.convoy.phase\" value=\"cancelled\"; }\n"
"  when kind=\"convoy\" visible-when=\"show-finished\" { match \"flotilla.convoy.phase\" value=\"abandoned\"; }\n"
"  when kind=\"vessel\" visible-when=\"show-finished\" { match \"flotilla.convoy.phase\" value=\"abandoned\"; }\n"
"  when kind=\"convoy\" visible-when=\"show-role-attempts\" { match \"flotilla.role\" exists=true; }\n"
"  when kind=\"vessel\" visible-when=\"show-role-attempts\" { match \"flotilla.role\" exists=true; }\n"
"  when kind=\"issue\" visible-when=\"show-issues\"\n"
"}\n"
"\n"
"region \"tree\" root-template=\"wheelhouse/projects\" form=\"compact\" placement=\"tree\"\n"
"region \"sessions\" root-template=\"wheelhouse/sessions\" form=\"compact\" placement=\"sessions\"\n"
"region \"attention\" root-template=\"wheelhouse/attention\" form=\"compact\" placement=\"attention\"\n"
"\n"
"template \"wheelhouse/projects\" slot=\"compact\" node-kind=\"entity\" {\n"
"  field \"label\" source=\"literal\" value=\"Projects\"\n"
"  control \"display-variable\" variable=\"show-issues\"\n"
"  control \"display-variable\" variable=\"show-finished\"\n"
"  control \"display-variable\" variable=\"show-role-attempts\"\n"
"}\n"
"template \"wheelhouse/sessions\" slot=\"compact\" node-kind=\"entity\" {\n"
"  field \"label\" source=\"literal\" value=\"Sessions\"\n"
"}\n"
"template \"wheelhouse/attention\" slot=\"compact\" node-kind=\"entity\" {\n"
"  field \"label\" source=\"literal\" value=\"Attention\"\n"
"}\n"
"\n"
"placement \"tree\" {\n"
"  for \"project\" kind=\"project\" {\n"
"    order \"display.label\"\n"
"    apply-template \"project/native\"\n"
"  }\n"
"}\n"
"template \"project/native\" {\n"
"  field \"label\" key=\"display.label\"\n"
"  // Standing roles (flotilla#1908) are actions on the project row, selected by\n"
"  // kind rather than by any convoy or role name.\n"
"  for \"role\" kind=\"role\" layout=\"inline\" {\n"
"    match \"flotilla.project\" of=\"project\"\n"
"    order \"flotilla.role.name\"\n"
"    apply-template \"wheelhouse/entry\"\n"
"  }\n"
"  for \"checkout\" kind=\"checkout\" {\n"
"    match \"flotilla.project\" of=\"project\"\n"
"    order \"display.label\"\n"
"    apply-template \"wheelhouse/entry\"\n"
"  }\n"
"  for \"convoy\" kind=\"convoy\" visibility=\"wheelhouse/activity\" {\n"
"    match \"flotilla.project\" of=\"project\"\n"
"    order \"display.label\"\n"
"    apply-template \"convoy/native\"\n"
"  }\n"
"  for \"issue\" kind=\"issue\" visibility=\"wheelhouse/activity\" {\n"
"    match \"flotilla.project\" of=\"project\"\n"
"    order \"display.label\"\n"
"    apply-template \"wheelhouse/entry\"\n"
"  }\n"
"}\n"
"template \"convoy/native\" {\n"
"  field \"label\" key=\"display.label\"\n"
"  field \"kind\" key=\"entity.kind\"\n"
"  field \"status\" key=\"status.state\"\n"
"  for \"vessel\" kind=\"vessel\" visibility=\"wheelhouse/activity\" layout=\"inline\" {\n"
"    match \"flotilla.convoy\" of=\"convoy\"\n"
"    order \"display.label\"\n"
"    apply-template \"wheelhouse/entry\"\n"
"  }\n"
"}\n"
"placement \"sessions\" {\n"
"  for \"session\" kind=\"session\" {\n"
"    order \"display.label\"\n"
"    apply-template \"wheelhouse/entry\"\n"
"  }\n"
"}\n"
"placement \"attention\" {\n"
"  for \"attention\" visibility=\"wheelhouse/activity\" {\n"
"    match \"status.attention\" value=\"true\"\n"
"    order \"display.label\"\n"
"    apply-template \"wheelhouse/attention-entry\"\n"
"  }\n"
"}\n"
"template \"wheelhouse/entry\" {\n"
"  field \"label\" key=\"display.label\"\n"
"  field \"kind\" key=\"entity.kind\"\n"
"  field \"status\" key=\"status.state\"\n"
"}\n"
"\n"
"// Context travels with detached Attention entries; the native renderer resolves\n"
"// these identities to labels when the corresponding project/convoy is present.\n"
"template \"wheelhouse/attention-entry\" {\n"
"  field \"label\" key=\"display.label\"\n"
"  field \"kind\" key=\"entity.kind\"\n"
"  field \"status\" key=\"status.state\"\n"
"  field \"project\" key=\"flotilla.project\"\n"
"  field \"convoy\" key=\"flotilla.convoy\"\n"
"}\n"
"\n"
"// Detail fields are independent of the compact row composition.\n"
"fragment \"wheelhouse/hover-details\" {\n"
"  field \"status\" key=\"status.state\" prefix=\"Status: \"\n"
"  field \"detail\" key=\"status.detail\"\n"
"  field \"phase\" key=\"flotilla.convoy.phase\" prefix=\"Phase: \"\n"
"  field \"host\" key=\"flotilla.vessel.host\" prefix=\"Host: \"\n"
"  field \"repo\" key=\"vcs.repo\" prefix=\"Repository: \"\n"
"  field \"branch\" key=\"checkout.branch\" prefix=\"Branch: \"\n"
"  field \"path\" key=\"checkout.path\" prefix=\"Path: \"\n"
"}\n"
"template \"project/detail\" slot=\"detail\" node-kind=\"entity\" {\n"
"  use \"wheelhouse/hover-details\"\n"
"  field \"convoys\" source=\"metadata-display\" key=\"count.convoys\" prefix=\"Convoys: \"\n"
"  field \"vessels\" source=\"metadata-display\" key=\"count.vessels\" prefix=\"Vessels: \"\n"
"  field \"issues\" source=\"metadata-display\" key=\"count.issues\" prefix=\"Issues: \"\n"
"  field \"checkouts\" source=\"metadata-display\" key=\"count.checkouts\" prefix=\"Checkouts: \"\n"
"  // Complete membership from the project definition (flotilla#1897), not\n"
"  // inferred from activity. Zero is known-empty; absence is unavailable.\n"
"  field \"repositories\" source=\"metadata-display\" key=\"flotilla.project.repository_count\" prefix=\"Repositories: \"\n"
"  for \"repository\" kind=\"project_repository\" {\n"
"    match \"flotilla.project\" of=\"project\"\n"
"    order \"display.label\"\n"
"    field \"repository\" key=\"display.label\" prefix=\"  \"\n"
"    field \"subpath\" key=\"flotilla.membership.subpath\" prefix=\"    path: \"\n"
"  }\n"
"}\n"
"template \"role/detail\" slot=\"detail\" node-kind=\"entity\" {\n"
"  field \"summary\" key=\"summary.text\"\n"
"  field \"role\" key=\"flotilla.role.name\" prefix=\"Role: \"\n"
"  field \"presents\" key=\"flotilla.role.presents_as\" prefix=\"Presents as: \"\n"
"  field \"hold\" key=\"flotilla.role.hold\" prefix=\"Held: \"\n"
"  field \"content\" key=\"workspace.primary.state\" prefix=\"Attachment: \"\n"
"  use \"wheelhouse/hover-details\"\n"
"}\n"
"template \"convoy/detail\" slot=\"detail\" node-kind=\"entity\" {\n"
"  field \"summary\" key=\"summary.text\"\n"
"  use \"wheelhouse/hover-details\"\n"
"}\n"
"template \"vessel/detail\" slot=\"detail\" node-kind=\"entity\" {\n"
"  field \"summary\" key=\"summary.text\"\n"
"  use \"wheelhouse/hover-details\"\n"
"}\n"
"template \"checkout/detail\" slot=\"detail\" node-kind=\"entity\" {\n"
"  field \"summary\" key=\"summary.text\"\n"
"  use \"wheelhouse/hover-details\"\n"
"}\n"
"template \"session/detail\" slot=\"detail\" node-kind=\"entity\" {\n"
"  field \"summary\" key=\"summary.text\"\n"
"  use \"wheelhouse/hover-details\"\n"
"}\n"
"template \"issue/detail\" slot=\"detail\" node-kind=\"entity\" {\n"
"  field \"summary\" key=\"summary.text\"\n"
"  use \"wheelhouse/hover-details\"\n"
"}\n"
"\n"
"// Host-independent git producer contract, shared with andamento-git.kdl.\n"
"region \"git\" root-template=\"wheelhouse/git\" form=\"compact\" placement=\"git\"\n"
"template \"wheelhouse/git\" slot=\"compact\" node-kind=\"entity\" {\n"
"  field \"label\" source=\"literal\" value=\"Git\"\n"
"}\n"
"placement \"git\" {\n"
"  for \"repo\" kind=\"repo\" layout=\"fields\" tier=\"medium\" {\n"
"    order \"display.label\"\n"
"    apply-template \"repo/native\"\n"
"  }\n"
"}\n"
"template \"repo/native\" {\n"
"  field \"label\" class=\"required\" key=\"display.label\"\n"
"  for \"worktree\" kind=\"worktree\" layout=\"fields\" tier=\"short\" {\n"
"    match \"git.repo\" of=\"repo\"\n"
"    order \"git.root\"\n"
"    apply-template \"worktree/native\"\n"
"  }\n"
"}\n"
"template \"worktree/native\" {\n"
"  field \"label\" class=\"optional\" key=\"display.label\"\n"
"  field \"branch\" class=\"required\" key=\"git.branch\"\n"
"  field \"dirty\" class=\"required\" key=\"git.dirty\" prefix=\"dirty:\"\n"
"  field \"ahead\" class=\"priority\" priority=20 key=\"git.ahead\" prefix=\"\u2191\"\n"
"  field \"behind\" class=\"priority\" priority=20 key=\"git.behind\" prefix=\"\u2193\"\n"
"}\n"
"template \"worktree/detail\" slot=\"detail\" node-kind=\"entity\" {\n"
"  field \"root\" key=\"git.root\" prefix=\"Path: \"\n"
"  field \"branch\" key=\"git.branch\" prefix=\"Branch: \"\n"
"  field \"dirty\" key=\"git.dirty\" prefix=\"Dirty: \"\n"
"  field \"upstream\" key=\"git.upstream\" prefix=\"Upstream: \"\n"
"}\n";
